# Feature: delay-prediction

`POST /api/predict` `Journey` -> `Prediction` (contract) plus additive per-leg
`distribution` (5 bins incl. cancelled), `quantiles` (p10/p50/p90) and `pCancel`.
Serves demo shot 0:30 "per-train delay, chained".

- `connection.js` -- JS port of `app/agents/src/features/db_delay/trip/connection.py` (change and journey probabilities).
- `backends/mock.js` -- deterministic fat-tailed prior by train class x hour x duration (`modelId: mock-prior-v1`, confidence low).
- `backends/http.js` -- forwards to `PREDICT_URL` (the Python model server); falls back to the mock and records `fallbackFrom`.
- Model server contract: `POST {legs:[{trainId, arrival:{probs[], pCancel}, departure?, reasoning?, sources?}], modelId?, confidence?}`.
---DP-ROUTES---
// delay-prediction: POST /api/predict  Journey -> Prediction (contract) plus
// additive per-leg fields: distribution (binned), quantiles (p10/p50/p90), pCancel.
// Per-leg forecasts come from a backend (mock prior, or the model server via
// PREDICT_URL); chaining across transfers is the JS port of connection.py.
import { changeProbability, journeyProbability, quantile, onTimeProbability, binned, minutesBetween } from '../connection.js';
import { createMockBackend } from '../backends/mock.js';
import { createHttpBackend } from '../backends/http.js';

const fail = (status, message, details) => Object.assign(new Error(message), { status, details });
const pct = (x) => `${Math.round(x * 100)}%`;
const r3 = (x) => Math.round(x * 1000) / 1000;

export function validateJourney(journey) {
  if (!journey || !Array.isArray(journey.legs) || journey.legs.length === 0) throw fail(400, 'Body must be a Journey with at least one leg');
  journey.legs.forEach((leg, i) => {
    for (const k of ['trainId', 'plannedDeparture', 'plannedArrival']) {
      if (typeof leg?.[k] !== 'string' || !leg[k]) throw fail(400, `legs[${i}].${k} is required`);
    }
    if (Number.isNaN(Date.parse(leg.plannedDeparture)) || Number.isNaN(Date.parse(leg.plannedArrival))) throw fail(400, `legs[${i}] has an unparseable planned time`);
  });
}

export function transferBuffer(legs, i) {
  const leg = legs[i];
  if (typeof leg.transferMinutes === 'number') return leg.transferMinutes;
  return minutesBetween(leg.plannedArrival, legs[i + 1].plannedDeparture);
}

export function createPredictionService({ env = process.env, backend, fetchImpl = fetch } = {}) {
  const mock = createMockBackend();
  const mode = env.PREDICT_BACKEND || (env.PREDICT_URL ? 'http' : 'mock');
  const chosen = backend ?? (mode === 'http'
    ? createHttpBackend({ url: env.PREDICT_URL, fetchImpl, timeoutMs: Number(env.PREDICT_TIMEOUT_MS || 8000) })
    : mock);
  const minTransfer = Number(env.MIN_TRANSFER_MINUTES || 5);

  return {
    minTransfer,
    async forecast(journey) {
      validateJourney(journey);
      try {
        return await chosen.forecast(journey);
      } catch (e) {
        if (chosen === mock) throw e;
        const f = await mock.forecast(journey);
        f.fallbackFrom = e.message;
        for (const l of f.legs) l.sources = [...l.sources, `fallback: model server unavailable (${e.message})`];
        return f;
      }
    },

    /** Pure: journey + per-leg forecasts -> Prediction. Reused by recommendation for what-ifs. */
    chain(journey, forecasts) {
      validateJourney(journey);
      const legs = journey.legs;
      const changes = [];
      const legDelays = legs.map((leg, i) => {
        const f = forecasts.legs[i];
        const p10 = quantile(f.arrival, 0.1), p50 = quantile(f.arrival, 0.5), p90 = quantile(f.arrival, 0.9);
        const onTime = onTimeProbability(f.arrival);
        const headline = `about +${p50} min, likely ${p10} to ${p90} min, ${pct(onTime)} chance of arriving on time`;
        const sources = [...(f.sources || []), forecasts.modelId];

        let miss;
        if (i < legs.length - 1) {
          const next = forecasts.legs[i + 1];
          const buffer = transferBuffer(legs, i);
          const departing = next.departure ?? next.arrival;
          const pMade = changeProbability(f.arrival, departing, buffer, minTransfer);
          changes.push([f.arrival, departing, buffer, minTransfer]);
          const station = leg.to?.name || 'the change station';
          miss = {
            value: r3(1 - pMade),
            reasoning: `${buffer} min planned at ${station}, ${minTransfer} min needed to change → ${Math.floor(buffer - minTransfer)} min of slack. ` +
              `P(${leg.trainId} arrives more than that behind ${legs[i + 1].trainId}) plus cancellations (${pct(f.arrival.pCancel ?? 0)} + ${pct(departing.pCancel ?? 0)}) gives ${pct(1 - pMade)}.`,
            sources,
            confidence: forecasts.confidence,
          };
        } else {
          miss = { value: 0, reasoning: 'Final leg — there is no connection left to miss.', sources, confidence: forecasts.confidence };
        }

        return {
          trainId: leg.trainId,
          expectedDelayMinutes: { value: p50, reasoning: `${headline}. ${f.reasoning || ''}`.trim(), sources, confidence: forecasts.confidence },
          missProbability: miss,
          distribution: binned(f.arrival),
          quantiles: { p10, p50, p90 },
          pCancel: f.arrival.pCancel ?? 0,
        };
      });

      const chained = journeyProbability(changes);
      const parts = chained.changeProbabilities.map((p) => `(1−${pct(1 - p)})`).join('·');
      return {
        journeyId: journey.id,
        legs: legDelays,
        planFailProbability: {
          value: r3(chained.planFail),
          reasoning: changes.length
            ? `1 − ${parts} = ${pct(chained.planFail)}. Changes are treated as independent, which is optimistic when one disruption hits both trains; DB holding a connecting train is not modelled.`
            : 'Single leg: the plan only fails if the train is cancelled or very late; no connections to miss.',
          sources: [...new Set(legDelays.flatMap((l) => l.expectedDelayMinutes.sources))],
          confidence: forecasts.confidence,
        },
        modelId: forecasts.modelId,
        ...(forecasts.fallbackFrom ? { fallbackFrom: forecasts.fallbackFrom } : {}),
      };
    },

    async predict(journey) {
      const f = await this.forecast(journey);
      return this.chain(journey, f);
    },
  };
}

export function registerRoutes(router, ctx = {}) {
  const svc = ctx.service || createPredictionService(ctx);
  router.post('/api/predict', ({ body }) => svc.predict(body));
  return svc;
}
---DP-HTTP---
// Forward a Journey to the Python model server (PREDICT_URL). Expected reply:
// { modelId?, confidence?, legs: [{ trainId, arrival: { probs, pCancel }, departure?, reasoning?, sources? }] }
// Any failure is thrown; the service falls back to the mock and says so.
export function createHttpBackend({ url, fetchImpl = fetch, timeoutMs = 8000 } = {}) {
  if (!url) throw new Error('PREDICT_URL is required for the http backend');
  return {
    modelId: 'remote',
    async forecast(journey) {
      const res = await fetchImpl(url, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify(journey),
        signal: AbortSignal.timeout(timeoutMs),
      });
      if (!res.ok) throw new Error(`model server replied ${res.status}`);
      const data = await res.json();
      if (!Array.isArray(data?.legs) || data.legs.length !== journey.legs.length) throw new Error('model server reply has no per-leg forecasts');
      for (const l of data.legs) if (!Array.isArray(l?.arrival?.probs)) throw new Error('model server leg is missing arrival.probs');
      return {
        modelId: data.modelId || 'OpenTSLM db-trip-delay (unversioned)',
        confidence: data.confidence || 'medium',
        legs: data.legs.map((l, i) => ({
          trainId: l.trainId || journey.legs[i].trainId,
          arrival: { probs: l.arrival.probs, pCancel: l.arrival.pCancel ?? 0 },
          departure: l.departure?.probs ? { probs: l.departure.probs, pCancel: l.departure.pCancel ?? 0 } : undefined,
          reasoning: l.reasoning || 'Fine-tuned model forecast.',
          sources: l.sources || [data.modelId || 'model server'],
        })),
      };
    },
  };
}
---DP-MOCK---
// Deterministic per-leg prior: a geometric delay distribution whose median
// depends on train class, departure hour and leg duration. Stands in for the
// fine-tuned model until PREDICT_URL serves it. No randomness, so the demo is
// byte-identical every run.
import { forecast, minutesBetween } from '../connection.js';

export const MODEL_ID = 'mock-prior-v1';
const LONG_DISTANCE = new Set(['ICE', 'IC', 'EC', 'ECE', 'TGV', 'RJ', 'RJX', 'NJ']);

export function trainClass(trainId = '') {
  return String(trainId).trim().split(/[\s\d]/)[0].toUpperCase();
}

function baseMedian(cls) {
  if (cls === 'ICE') return 8;
  if (LONG_DISTANCE.has(cls)) return 5;
  if (cls === 'S') return 2;
  return 3; // RE, RB, IRE, IR, BRB, ag, ALX, M, MEX, FEX ...
}

function hourFactor(iso) {
  const h = Number(new Intl.DateTimeFormat('en-GB', { hour: 'numeric', hour12: false, timeZone: 'Europe/Berlin' }).format(new Date(iso)));
  if (h >= 6 && h < 10) return 0.9;
  if (h >= 15 && h < 20) return 1.3;
  if (h >= 22 || h < 5) return 0.8;
  return 1.0;
}

/** Geometric pmf with its median exactly at `median`. */
export function geometric(median, size = 240) {
  const q = 0.5 ** (1 / (median + 1));
  const probs = new Array(size);
  for (let k = 0; k < size; k++) probs[k] = (1 - q) * q ** k;
  return probs;
}

/**
 * Real delay distributions have a fat tail: most runs are a few minutes late,
 * a minority hit a disruption and run 20-60 min late. Mix a routine geometric
 * with a disruption geometric so transfers under ~15 min carry visible risk.
 */
export function fatTailed(median, size = 240, disruptionShare = 0.18) {
  const routine = geometric(median, size);
  const disrupted = geometric(median * 4 + 12, size);
  return routine.map((p, k) => (1 - disruptionShare) * p + disruptionShare * disrupted[k]);
}

export function describeLeg(leg) {
  const cls = trainClass(leg.trainId);
  const hours = Math.max(0.25, minutesBetween(leg.plannedDeparture, leg.plannedArrival) / 60);
  const factor = hourFactor(leg.plannedDeparture) * (1 + 0.15 * hours);
  const median = Math.max(1, Math.round(baseMedian(cls) * factor));
  const pCancel = LONG_DISTANCE.has(cls) ? 0.02 : 0.03;
  return { cls, hours, median, pCancel };
}

export function createMockBackend({ size = 240 } = {}) {
  return {
    modelId: MODEL_ID,
    async forecast(journey) {
      return {
        modelId: MODEL_ID,
        confidence: 'low',
        legs: journey.legs.map((leg) => {
          const { cls, hours, median, pCancel } = describeLeg(leg);
          const hh = new Intl.DateTimeFormat('en-GB', { hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Berlin' }).format(new Date(leg.plannedDeparture));
          return {
            trainId: leg.trainId,
            arrival: forecast(fatTailed(median, size), pCancel),
            departure: forecast(fatTailed(Math.max(1, Math.round(median * 0.4)), size, 0.08), pCancel),
            reasoning: `Prior for ${cls} departing ${hh} on a ${hours.toFixed(1)} h leg: typical +${median} min; no live data behind this number.`,
            sources: ['mock: train-class × hour × duration prior v1'],
          };
        }),
      };
    },
  };
