test('tail-sum matches the brute-force double sum for geometric-ish delays', () => {
  const k = Array.from({ length: 200 }, (_, i) => i);
  const a = forecast(k.map((x) => Math.exp(-x / 6)));
  const d = forecast(k.map((x) => Math.exp(-x / 3)));
